#' Campionamento sistematico
#'
#' 
#' @param data .
#' @param id_var Variabile usata per identificare le singole unità nel
#'   dataset. Se specificata, la tabella "Unità estratte" mostra gli ID dei
#'   soggetti selezionati.
#' @param sort_var Se specificata, le unità della popolazione vengono ordinate
#'   in base ai valori di questa variabile prima di applicare l'intervallo di
#'   campionamento. L'efficienza del sistematico dipende criticamente
#'   dall'ordinamento.
#' @param tuto .
#' @param size_mode Indica se il campione è definito tramite un numero
#'   assoluto di unità (n) oppure tramite una frazione f della popolazione.
#' @param n Numerosità del campione da estrarre.
#' @param f Frazione f = n/N della popolazione da estrarre.
#' @param seed Seme del generatore casuale, usato per estrarre la partenza r
#'   in (0, k] con k = N/n, unico numero casuale del disegno (sistematico a
#'   intervallo frazionario). Garantisce la riproducibilità del campione.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$extracted} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$out_freq} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
samplesyst <- function(
    data,
    id_var,
    sort_var,
    tuto = TRUE,
    size_mode = "n",
    n = 30,
    f = 0.1,
    seed = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("samplesyst requires jmvcore to be installed (restart may be required)")

    if ( ! missing(id_var)) id_var <- jmvcore::resolveQuo(jmvcore::enquo(id_var))
    if ( ! missing(sort_var)) sort_var <- jmvcore::resolveQuo(jmvcore::enquo(sort_var))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(id_var), id_var, NULL),
            `if`( ! missing(sort_var), sort_var, NULL))


    options <- samplesystOptions$new(
        id_var = id_var,
        sort_var = sort_var,
        tuto = tuto,
        size_mode = size_mode,
        n = n,
        f = f,
        seed = seed)

    analysis <- samplesystClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

